<template>
  <div class="maint-shell">
    <aside><div class="logo"><el-icon><Tools /></el-icon><div><b>福州国家森林公园</b><span>古树防火巡护平台</span></div></div><el-menu :default-active="active" @select="selectMenu"><el-menu-item index="back"><el-icon><Back /></el-icon>返回防火态势</el-menu-item><el-menu-item index="alerts"><el-icon><Warning /></el-icon>设备异常<span v-if="openFaults" class="count" :aria-label="`待处理异常 ${openFaults} 条`"><b>{{ openFaults > 99 ? '99+' : openFaults }}</b></span></el-menu-item><el-menu-item index="ledger"><el-icon><List /></el-icon>设备台账</el-menu-item><el-menu-item index="history"><el-icon><Clock /></el-icon>运维记录</el-menu-item></el-menu><div class="user"><el-avatar>{{ userName.charAt(0) }}</el-avatar><div><b>{{ userName }}</b><span>护林员</span></div><el-button text circle @click="logout"><el-icon><SwitchButton /></el-icon></el-button></div></aside>
    <main><header><div><span>RANGER EQUIPMENT CENTER</span><h1>{{ titles[active] }}</h1><p>设备异常统一推送给护林员，集中查看传感器、摄像头、广播和无人机状态</p></div><el-button v-if="active==='ledger'" type="primary" @click="openAdd">＋ 登记设备</el-button></header>
      <section class="stats"><article><div class="icon green"><el-icon><Monitor /></el-icon></div><div><span>设备总数</span><b>{{ devices.length }}</b><small>覆盖4类防火设备</small></div></article><article><div class="icon orange"><el-icon><Warning /></el-icon></div><div><span>待处理异常</span><b>{{ openFaults }}</b><small>离线与电池异常</small></div></article><article><div class="icon blue"><el-icon><CircleCheck /></el-icon></div><div><span>设备在线率</span><b>{{ onlineRate }}%</b><small>目标不低于95%</small></div></article><article><div class="icon gray"><el-icon><Calendar /></el-icon></div><div><span>本月处置记录</span><b>{{ history.length }}</b><small>含巡检与设备自检</small></div></article></section>
      <el-card v-if="active==='alerts'" shadow="never"><template #header><div class="card-head"><div><b>设备故障与离线信息</b><span>护林员确认异常、安排现场检查并记录恢复结果</span></div><el-button @click="loadEquipment">刷新状态</el-button></div></template><el-table :data="faults" border stripe><el-table-column prop="id" label="告警编号" width="145"/><el-table-column prop="device" label="设备" min-width="160"/><el-table-column prop="location" label="位置" min-width="160"/><el-table-column prop="type" label="异常类型" width="130"/><el-table-column prop="time" label="发生时间" width="165"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.status==='pending'?'danger':s.row.status==='accepted'?'warning':'success'">{{ faultStatus(s.row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="190"><template #default="s"><el-button v-if="s.row.status==='pending'" type="primary" size="small" @click="acceptFault(s.row)">确认异常</el-button><el-button v-else-if="s.row.status==='accepted'" type="success" size="small" @click="openRepair(s.row)">记录恢复</el-button><el-button v-else size="small" @click="showFault(s.row)">查看记录</el-button></template></el-table-column></el-table></el-card>
      <el-card v-else-if="active==='ledger'" shadow="never"><template #header><div class="card-head"><div><b>森林防火设备台账</b><span>护林员统一查看设备位置、数据来源和运行状态</span></div><el-input v-model="keyword" clearable placeholder="搜索设备编号或名称" style="width:230px"/></div></template><el-table :data="filteredDevices" border stripe><el-table-column prop="id" label="设备编号" width="115"/><el-table-column prop="name" label="设备名称" min-width="150"/><el-table-column prop="type" label="设备类型" width="115"/><el-table-column prop="location" label="安装位置" min-width="150"/><el-table-column prop="source" label="数据类型" width="90"><template #default="s"><el-tag size="small" :type="s.row.source==='真机'?'success':'info'">{{ s.row.source }}</el-tag></template></el-table-column><el-table-column label="最近自检" width="135"><template #default="s"><button v-if="latestSelfTest(s.row.id)" class="self-test-link" @click="showSelfTest(latestSelfTest(s.row.id))"><i :class="latestSelfTest(s.row.id).status"></i><span>{{ selfTestStatus(latestSelfTest(s.row.id).status) }}</span><small>{{ shortTime(latestSelfTest(s.row.id).completeTime||latestSelfTest(s.row.id).requestTime) }}</small></button><span v-else class="no-test">尚未自检</span></template></el-table-column><el-table-column label="状态" width="95"><template #default="s"><el-tag :type="deviceInfo(s.row.status).type">{{ deviceInfo(s.row.status).text }}</el-tag></template></el-table-column><el-table-column label="操作" width="235" fixed="right"><template #default="s"><el-button size="small" @click="openLedger(s.row)">详情</el-button><el-button size="small" type="warning" plain :loading="selfTestRunningId===s.row.id" :disabled="s.row.status==='retired'" @click="startDeviceSelfTest(s.row)">发起自检</el-button><el-popconfirm title="确认将该设备停用？" @confirm="retire(s.row)"><template #reference><el-button size="small" type="danger" plain :disabled="s.row.status==='retired'">停用</el-button></template></el-popconfirm></template></el-table-column></el-table></el-card>
      <el-card v-else shadow="never"><template #header><div class="card-head"><div><b>设备异常与运维记录</b><span>留存自检和恢复结果，为护林员安排后续维护提供依据</span></div><el-select v-model="historyType" style="width:160px"><el-option label="全部设备" value="all"/><el-option label="无人机" value="无人机"/><el-option label="传感节点" value="传感节点"/><el-option label="摄像头" value="摄像头"/></el-select></div></template><el-table :data="filteredHistory" border stripe><el-table-column prop="time" label="记录时间" width="165"/><el-table-column prop="device" label="设备" min-width="170"/><el-table-column prop="type" label="设备类型" width="110"/><el-table-column prop="fault" label="异常现象" min-width="170"/><el-table-column prop="result" label="处置结果" min-width="210"/><el-table-column prop="operator" label="记录人" width="110"/><el-table-column label="结果" width="90"><template #default><el-tag type="success">已恢复</el-tag></template></el-table-column></el-table></el-card>
    </main>
    <el-dialog v-model="addVisible" title="新增防火设备" width="560px"><el-form label-position="top"><el-form-item label="设备编号"><el-input v-model="form.id"/></el-form-item><el-form-item label="设备名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="设备类型"><el-select v-model="form.type" style="width:100%"><el-option label="传感节点" value="传感节点"/><el-option label="固定摄像头" value="固定摄像头"/><el-option label="广播设备" value="广播设备"/><el-option label="无人机" value="无人机"/></el-select></el-form-item><el-form-item label="安装或存放位置"><el-input v-model="form.location"/></el-form-item><el-form-item label="数据来源"><el-select v-model="form.source" style="width:100%"><el-option label="真实设备" value="真机"/><el-option label="仿真接入" value="仿真"/></el-select></el-form-item><template v-if="mapDevice"><el-form-item label="所属分区"><el-select v-model="form.zone" style="width:100%"><el-option v-for="z in zones" :key="z.id" :label="z.name" :value="z.name"/></el-select></el-form-item><div class="coordinate-grid"><el-form-item label="经度"><el-input-number v-model="form.longitude" :precision="6" :step="0.0001" :controls="false"/></el-form-item><el-form-item label="纬度"><el-input-number v-model="form.latitude" :precision="6" :step="0.0001" :controls="false"/></el-form-item></div><el-alert title="传感节点和无人机会同步显示在地图上，坐标必须位于公园边界内。" type="info" :closable="false" show-icon/></template></el-form><template #footer><el-button @click="addVisible=false">取消</el-button><el-button type="primary" @click="addDevice">保存设备</el-button></template></el-dialog>
    <el-dialog v-model="repairVisible" title="提交设备恢复记录" width="520px"><el-form label-position="top"><el-form-item label="目标设备"><el-input :model-value="repairTarget?.device||repairTarget?.name" disabled/></el-form-item><el-form-item label="维修与恢复结果"><el-input v-model="repairRemark" type="textarea" :rows="4" placeholder="填写现场发现的原因、处理措施及恢复验证结果"/></el-form-item></el-form><template #footer><el-button @click="repairVisible=false">取消</el-button><el-button type="primary" @click="finishRepair">保存恢复记录</el-button></template></el-dialog>
    <el-dialog v-model="selfTestVisible" title="设备主动自检" width="660px" :close-on-click-modal="false"><div v-if="selfTestRecord" class="self-test-panel"><div class="self-test-hero" :class="selfTestRecord.status"><div class="test-hero-icon"><el-icon v-if="selfTestRecord.status==='running'" class="self-test-spinner"><Loading /></el-icon><el-icon v-else-if="selfTestRecord.status==='passed'"><CircleCheck /></el-icon><el-icon v-else><Warning /></el-icon></div><div><span>{{ selfTestRecord.testNo }}</span><h3>{{ selfTestRecord.deviceName }}</h3><p>{{ selfTestRecord.status==='running'?'正在等待仿真固件逐项返回检查结果':selfTestRecord.summary }}</p></div><el-tag size="large" :type="selfTestRecord.status==='passed'?'success':selfTestRecord.status==='failed'?'danger':'warning'">{{ selfTestStatus(selfTestRecord.status) }}</el-tag></div><div class="test-meta"><span>设备类型<b>{{ selfTestRecord.deviceType }}</b></span><span>执行方式<b>仿真固件回执</b></span><span>发起时间<b>{{ selfTestRecord.requestTime }}</b></span></div><div v-if="selfTestRecord.status==='running'" class="test-running"><el-progress :percentage="selfTestProgress" :stroke-width="8" striped striped-flow/><div v-for="i in 4" :key="i" class="test-skeleton"><i></i><span></span><em></em></div></div><div v-else class="test-checks"><article v-for="check in selfTestRecord.checks" :key="check.name" :class="check.status"><div class="check-icon"><el-icon><CircleCheck v-if="check.status==='passed'"/><Warning v-else/></el-icon></div><div><b>{{ check.name }}</b><span>{{ check.value }}</span><small>判定标准：{{ check.standard }}</small></div><el-tag :type="check.status==='passed'?'success':'danger'">{{ check.status==='passed'?'通过':'异常' }}</el-tag></article></div><el-alert v-if="selfTestRecord.status==='failed'" title="失败项目已自动生成设备异常，无需人工录入故障原因。" type="error" :closable="false" show-icon/></div><template #footer><el-button @click="selfTestVisible=false">关闭</el-button><el-button v-if="selfTestRecord?.status==='failed'" type="primary" @click="selfTestVisible=false;active='alerts'">查看设备异常</el-button></template></el-dialog>
    <el-drawer v-model="detailVisible" title="设备档案" size="430px"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="设备编号">{{ detail.id }}</el-descriptions-item><el-descriptions-item label="设备名称">{{ detail.name||detail.device }}</el-descriptions-item><el-descriptions-item label="设备类型">{{ detail.type }}</el-descriptions-item><el-descriptions-item label="安装位置">{{ detail.location }}</el-descriptions-item><el-descriptions-item label="最近维护">{{ detail.lastMaintain||detail.time||'暂无记录' }}</el-descriptions-item><el-descriptions-item label="当前状态">{{ detail.status?deviceInfo(detail.status).text:'已恢复' }}</el-descriptions-item></el-descriptions><div v-if="latestSelfTest(detail.id)" class="drawer-test"><span>最近一次主动自检</span><b>{{ selfTestStatus(latestSelfTest(detail.id).status) }} · {{ latestSelfTest(detail.id).completeTime||latestSelfTest(detail.id).requestTime }}</b><p>{{ latestSelfTest(detail.id).summary||'设备正在执行检查项目' }}</p><el-button size="small" @click="showSelfTest(latestSelfTest(detail.id))">查看自检明细</el-button></div></template></el-drawer>
  </div>
</template>
<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Tools, Warning, List, Clock, SwitchButton, Monitor, CircleCheck, Calendar, Back, Loading } from '@element-plus/icons-vue'
import { addForestEquipment, addForestMaintenance, getForestBootstrap, getForestEquipment, getForestEquipmentSelfTest, startForestEquipmentSelfTest, updateForestEquipmentStatus, updateForestFault } from '@/api/forest'
import { PARK, isPointInPark } from '@/config/park'

const router=useRouter(),active=ref('alerts'),keyword=ref(''),historyType=ref('all'),addVisible=ref(false),repairVisible=ref(false),detailVisible=ref(false),detail=ref(null),repairTarget=ref(null),repairRemark=ref('')
const selfTestVisible=ref(false),selfTestRecord=ref(null),selfTestRunningId=ref(''),selfTestProgress=ref(12)
const user=JSON.parse(localStorage.getItem('currentUser')||'{}'),userName=computed(()=>user.username||'护林员')
const titles={alerts:'设备异常',ledger:'设备台账',history:'运维记录'}
const devices=ref([]),faults=ref([]),history=ref([]),selfTests=ref([]),zones=ref([])
const openFaults=computed(()=>faults.value.filter(f=>f.status!=='closed').length)
const onlineRate=computed(()=>{const activeDevices=devices.value.filter(d=>d.status!=='retired');return activeDevices.length?Math.round(devices.value.filter(d=>d.status==='online').length/activeDevices.length*100):0})
const filteredDevices=computed(()=>devices.value.filter(d=>!keyword.value||`${d.id}${d.name}`.includes(keyword.value)))
const filteredHistory=computed(()=>historyType.value==='all'?history.value:history.value.filter(h=>h.type===historyType.value))
const emptyForm=()=>({id:'',name:'',type:'传感节点',location:'',source:'仿真',zone:zones.value[0]?.name||'',longitude:PARK.center[0],latitude:PARK.center[1]})
const form=ref(emptyForm())
const mapDevice=computed(()=>['传感节点','无人机'].includes(form.value.type))
const faultStatus=s=>({pending:'待确认',accepted:'跟进中',closed:'已恢复'}[s])
const deviceInfo=s=>({online:{text:'在线',type:'success'},offline:{text:'离线',type:'danger'},warning:{text:'需关注',type:'warning'},retired:{text:'已停用',type:'info'}}[s]||{text:s,type:'info'})
const selfTestStatus=s=>({running:'执行中',passed:'全部通过',failed:'发现异常',timeout:'执行超时'}[s]||'等待执行')
const latestSelfTest=id=>selfTests.value.find(v=>v.deviceId===id)
const shortTime=value=>value?String(value).slice(5,16):'—'

async function loadEquipment(quiet=false){try{const [res,forest]=await Promise.all([getForestEquipment(),getForestBootstrap()]);if(res.code!==200)throw new Error();devices.value=res.data?.devices||[];faults.value=res.data?.faults||[];history.value=res.data?.history||[];selfTests.value=res.data?.selfTests||[];zones.value=forest.data?.zones||[]}catch{if(!quiet)ElMessage.error('设备数据加载失败，请检查后端与数据库')}}
let equipmentPoll,selfTestPoll,progressTimer
onMounted(()=>{loadEquipment();equipmentPoll=setInterval(()=>loadEquipment(true),5000)})
onUnmounted(()=>{clearInterval(equipmentPoll);clearInterval(progressTimer);clearTimeout(selfTestPoll)})
function selectMenu(key){if(key==='back'){router.push('/ranger');return}active.value=key}
async function acceptFault(f){try{await updateForestFault(f.id,{status:'accepted'});f.status='accepted';ElMessage.success('异常状态已保存')}catch{ElMessage.error('异常状态保存失败')}}
function openRepair(v){repairTarget.value=v;repairRemark.value='';repairVisible.value=true}
async function finishRepair(){if(!repairRemark.value.trim())return ElMessage.warning('请填写维修与恢复结果');const t=repairTarget.value,deviceId=t.deviceId||t.id,d=devices.value.find(v=>v.id===deviceId);try{await addForestMaintenance({faultId:t.device?t.id:'',deviceId,device:t.device||`${t.name} ${t.id}`,type:d?.type||t.type,fault:t.device?t.type:'人工巡检',result:repairRemark.value,operator:userName.value});repairVisible.value=false;await loadEquipment();ElMessage.success('设备恢复记录已写入数据库')}catch{ElMessage.error('恢复记录保存失败')}}
async function startDeviceSelfTest(device){if(selfTestRunningId.value)return;selfTestRunningId.value=device.id;selfTestVisible.value=true;selfTestProgress.value=12;selfTestRecord.value={deviceId:device.id,deviceName:device.name,deviceType:device.type,status:'running',checks:[],requestTime:'正在创建任务'};clearInterval(progressTimer);progressTimer=setInterval(()=>{selfTestProgress.value=Math.min(88,selfTestProgress.value+Math.round(Math.random()*12+4))},350);try{const res=await startForestEquipmentSelfTest(device.id);if(res.code!==200)throw new Error(res.msg||'自检任务创建失败');selfTestRecord.value=res.data;pollSelfTest(res.data.testNo)}catch(err){clearInterval(progressTimer);selfTestRunningId.value='';selfTestVisible.value=false;ElMessage.error(err.message||'自检任务创建失败')}}
function pollSelfTest(testNo){clearTimeout(selfTestPoll);selfTestPoll=setTimeout(async()=>{try{const res=await getForestEquipmentSelfTest(testNo);if(res.code!==200)throw new Error(res.msg||'自检结果读取失败');selfTestRecord.value=res.data;if(res.data.status==='running'){pollSelfTest(testNo);return}clearInterval(progressTimer);selfTestProgress.value=100;selfTestRunningId.value='';await loadEquipment(true);res.data.status==='passed'?ElMessage.success('设备主动自检全部通过'):ElMessage.warning('自检发现异常，已自动生成设备故障')}catch(err){clearInterval(progressTimer);selfTestRunningId.value='';ElMessage.error(err.message||'自检结果读取失败')}},700)}
function showSelfTest(record){selfTestRecord.value=record;selfTestVisible.value=true;if(record.status==='running'){selfTestRunningId.value=record.deviceId;pollSelfTest(record.testNo)}}
function showFault(f){detail.value=f;detailVisible.value=true}
function openLedger(d){detail.value=d;detailVisible.value=true}
function openAdd(){form.value=emptyForm();addVisible.value=true}
async function addDevice(){if(!form.value.id||!form.value.name||!form.value.location)return ElMessage.warning('请填写完整信息');if(mapDevice.value&&!form.value.zone)return ElMessage.warning('请选择所属分区');if(mapDevice.value&&!isPointInPark(form.value.longitude,form.value.latitude))return ElMessage.warning('设备坐标不在福州国家森林公园边界内，请重新填写');try{const res=await addForestEquipment(form.value);if(res.code!==200)throw new Error(res.msg||'设备登记失败');addVisible.value=false;await loadEquipment();ElMessage.success(mapDevice.value?'设备已登记，并同步加入园区地图':'防火设备已登记到数据库')}catch(err){ElMessage.error(err?.message||'设备登记失败，请检查编号、坐标是否正确')}}
async function retire(d){try{await updateForestEquipmentStatus(d.id,{status:'retired'});d.status='retired';ElMessage.success(`${d.name}已停用，历史记录继续保留`)}catch{ElMessage.error('设备状态保存失败')}}
// 兼容当前按钮：刷新数据库中的真实异常状态，不再在浏览器生成假故障。
async function simulateFault(){await loadEquipment();ElMessage.success('设备异常状态已从数据库刷新')}
function logout(){ElMessageBox.confirm('确定退出护林员工作台吗？','提示',{type:'warning'}).then(()=>{localStorage.removeItem('token');localStorage.removeItem('currentUser');router.push('/login')}).catch(()=>{})}
</script>
