.maint-shell{min-height:100vh;background:linear-gradient(145deg,#f5f7f2,#edf2eb);color:#20352a;display:flex}.maint-shell aside{width:230px;background:linear-gradient(180deg,#123c2a,#183f2e 62%,#102f22);color:#fff;position:fixed;inset:0 auto 0 0;display:flex;flex-direction:column;box-shadow:12px 0 34px rgba(18,57,40,.08)}.logo{height:82px;padding:0 20px;display:flex;align-items:center;gap:12px;border-bottom:1px solid rgba(255,255,255,.08)}.logo>.el-icon{font-size:27px;color:#a7d3b0}.logo b,.logo span{display:block}.logo span{font-size:10px;letter-spacing:.13em;color:#9cb6a5;margin-top:4px}.maint-shell aside .el-menu{background:transparent;border:0;padding:14px 10px}.maint-shell aside :deep(.el-menu-item){color:#b9ccbf;border-radius:10px;margin:4px 0;transition:.24s ease}.maint-shell aside :deep(.el-menu-item.is-active){background:linear-gradient(90deg,#2d6b4b,#347455);color:#fff;box-shadow:0 8px 20px rgba(5,30,19,.18)}.maint-shell aside :deep(.el-menu-item:hover){background:rgba(99,159,119,.18);color:#fff;transform:translateX(2px)}.count{font-style:normal;margin-left:auto;background:#d95f52;color:#fff;font-size:9px;font-weight:700;min-width:16px;height:16px;padding:0 4px;border-radius:8px;display:grid;place-items:center;box-shadow:0 0 0 3px rgba(217,95,82,.12)}.user{margin-top:auto;padding:16px;display:flex;align-items:center;gap:10px;border-top:1px solid rgba(255,255,255,.08)}.user>div{flex:1}.user b,.user span{display:block}.user span{font-size:10px;color:#9cb6a5;margin-top:4px}.user .el-avatar{background:#72ac80}.user .el-button{color:#bdd0c2}.maint-shell main{margin-left:230px;width:calc(100% - 230px);padding:26px 28px;animation:maintIn .4s ease-out}.maint-shell header{display:flex;justify-content:space-between;align-items:end;margin-bottom:22px}.maint-shell header>div>span{font-size:10px;letter-spacing:.18em;color:#769082}.maint-shell h1{font-size:27px;margin:6px 0}.maint-shell header p{font-size:13px;color:#788a80}.maint-shell :deep(.el-button--primary){backgro